const MAX_N=10;const MAX_SOLUTIONS=1024;
fn visit(nums:[*]const i64,n:usize,target:i64,start:usize,current:i64,remaining:i64,path:*[MAX_N]i64,depth:usize,sol:*[MAX_SOLUTIONS][MAX_N]i64,lens:*[MAX_SOLUTIONS]usize,count:*usize)void{if(current>target or remaining+current<target)return;if(current==target){lens[count.*]=depth;for(0..depth)|j|sol[count.*][j]=path[j];count.*+=1;return;}for(start..n)|i|{path[depth]=nums[i];visit(nums,n,target,i+1,current+nums[i],remaining-nums[i],path,depth+1,sol,lens,count);}}
fn put64(out:[*]u8,pos:*usize,x:i64)void{const u:@TypeOf(@as(u64,0))=@bitCast(x);for(0..8)|j|{out[pos.*]=@truncate(u>>(8*j));pos.*+=1;}}
export fn sum_of_subsets(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<2)return -1;const p=input.?;const nn=p[0];const target=p[1];if(nn<0 or nn>10 or length!=@as(usize,@intCast(nn))+2 or target<0 or target>250)return -1;const n:usize=@intCast(nn);var rem:i64=0;for(0..n)|i|{const x=p[2+i];if(x<0 or x>50)return -1;rem+=x;}var sol: [MAX_SOLUTIONS][MAX_N]i64 = @splat(@splat(0));var lens: [MAX_SOLUTIONS]usize = @splat(0);var path: [MAX_N]i64 = @splat(0);var count:usize=0;visit(p+2,n,target,0,0,rem,&path,0,&sol,&lens,&count);var need:usize=8;for(0..count)|i|need+=8+8*lens[i];if(output==null or capacity<need)return -2;const out=output.?;var pos:usize=0;put64(out,&pos,@intCast(count));for(0..count)|i|{put64(out,&pos,@intCast(lens[i]));for(0..lens[i])|j|put64(out,&pos,sol[i][j]);}return @intCast(pos);}
